-- TVD Repuestos: catálogo y compatibilidades.
create table public.catalog_admins (user_id uuid primary key references auth.users(id) on delete cascade);
create table public.categories (id bigint generated always as identity primary key, name text not null unique);
create table public.vehicles (id bigint generated always as identity primary key, make text not null, model text not null, year integer not null check (year between 1886 and 2100), version text not null, unique(make, model, year, version));
create table public.products (id uuid primary key default gen_random_uuid(), category_id bigint not null references public.categories(id), name text not null, description text not null default '', brand text not null default '', image_url text, published boolean not null default false, created_at timestamptz not null default now());
create table public.product_vehicles (product_id uuid not null references public.products(id) on delete cascade, vehicle_id bigint not null references public.vehicles(id) on delete cascade, primary key(product_id,vehicle_id));
create index product_vehicles_vehicle_idx on public.product_vehicles(vehicle_id,product_id);
create index products_category_idx on public.products(category_id) where published;
alter table public.catalog_admins enable row level security;
alter table public.categories enable row level security;
alter table public.vehicles enable row level security;
alter table public.products enable row level security;
alter table public.product_vehicles enable row level security;
grant select on public.categories,public.vehicles,public.products,public.product_vehicles to anon,authenticated;
grant select on public.catalog_admins to authenticated;
grant insert,update,delete on public.categories,public.vehicles,public.products,public.product_vehicles to authenticated;
grant usage,select on all sequences in schema public to authenticated;
create policy admin_self_read on public.catalog_admins for select to authenticated using (user_id=(select auth.uid()));
create policy categories_public_read on public.categories for select to anon,authenticated using (true);
create policy vehicles_public_read on public.vehicles for select to anon,authenticated using (true);
create policy products_public_read on public.products for select to anon,authenticated using (published);
create policy fits_public_read on public.product_vehicles for select to anon,authenticated using (exists(select 1 from public.products p where p.id=product_id and p.published));
create policy categories_admin on public.categories for all to authenticated using (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid()))) with check (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
create policy vehicles_admin on public.vehicles for all to authenticated using (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid()))) with check (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
create policy products_admin on public.products for all to authenticated using (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid()))) with check (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
create policy fits_admin on public.product_vehicles for all to authenticated using (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid()))) with check (exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
insert into public.categories(name) values ('Filtros'),('Bujías'),('Amortiguadores'),('Resortes'),('Rodamientos y cubos de rueda'),('Juntas homocinéticas y capuchones'),('Rótulas'),('Estabilizadores de suspensión'),('Terminales de dirección'),('Sensores');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('catalog-images','catalog-images',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy catalog_images_insert on storage.objects for insert to authenticated with check (bucket_id='catalog-images' and exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
create policy catalog_images_update on storage.objects for update to authenticated using (bucket_id='catalog-images' and exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid()))) with check (bucket_id='catalog-images' and exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
create policy catalog_images_delete on storage.objects for delete to authenticated using (bucket_id='catalog-images' and exists(select 1 from public.catalog_admins a where a.user_id=(select auth.uid())));
